// A single measured flow for the whole ritual list: shared fonts and spacing.
function defaultMeasure(text,size,family,bold){const ctx=globalThis.document?.createElement?.('canvas')?.getContext?.('2d');if(!ctx)return String(text).length*size*.58;ctx.font=`${bold?'bold ':''}${size}px ${family}`;return ctx.measureText(text).width;}
export function wrapRitualText(value,width,size,family,bold,measure=defaultMeasure){const result=[];for(const raw of String(value??'').replace(/\r/g,'').split('\n')){const paragraph=raw.trim().replace(/[ \t]+/g,' ');if(!paragraph){result.push('');continue;}let line='';for(const word of paragraph.split(' ')){const candidate=line?line+' '+word:word;if(measure(candidate,size,family,bold)<=width){line=candidate;continue;}if(line){result.push(line);line='';}if(measure(word,size,family,bold)<=width){line=word;continue;}for(const char of word){if(line&&measure(line+char,size,family,bold)>width){result.push(line);line='';}line+=char;}}result.push(line);}return result;}
export function layoutRituals(b,d,{measure=defaultMeasure,fit=false}={}){const ts=b.textStyle||{},title=b.titleStyle||{},requested=Number(ts.size)||Math.min(b.font||24,22),requestedTitle=Number(title.size)||Math.min(25,(b.font||24)+1),min=Math.min(requested,Math.max(8,Number(b.minFont)||12)),padding=Math.max(0,Number(ts.padding)||5),width=Math.max(1,b.w-2*padding),family=ts.family||d.theme?.bodyFont||'Arial',titleFamily=title.family||family,lineFactor=Math.max(.8,Number(ts.lineHeight)||1.42),gap=Math.max(4,Number(b.ritualGap)||20),header=b.part==='content'?0:56;function compose(size){const titleSize=requestedTitle*size/requested,titleLine=titleSize*1.2,lineHeight=size*lineFactor;let cursor=header+padding;const items=(d.rituals||[]).map(r=>{const titleLines=wrapRitualText(String(r.title).toUpperCase(),width,titleSize,titleFamily,title.bold!==false,measure),bodyLines=wrapRitualText(r.summary||r.body,width,size,family,!!ts.bold,measure),y=cursor,titleHeight=titleLines.length*titleLine,bodyY=y+titleHeight+Math.max(6,size*.3),bodyHeight=bodyLines.length*lineHeight;cursor=bodyY+bodyHeight+gap;return {id:r.id,y,titleLines,bodyLines,titleSize,size,titleHeight,bodyY,bodyHeight,bottom:bodyY+bodyHeight};});return {items,size,titleSize,family,titleFamily,padding,width,lineHeight,titleLine,gap,height:Math.ceil((items.length?cursor-gap:header)+padding)};}let result=compose(requested);if(fit&&b.autoFit!==false)while(result.height>b.h&&result.size>min)result=compose(Math.max(min,result.size-1));return {...result,overflow:result.height>b.h};}
